// /job/tmp/send-tg.js
const https = require('https');
const token = process.env.TELEGRAM_BOT_TOKEN;
const chatId = process.env.TELEGRAM_CHAT_ID;
const text = "**Top pair to watch today**: **GBP/JPY** at **211.0050** - Bullish, key level **214.98**. \n**GBP/JPY Status**: Bullish.\n**Key Economic Events**: March 10 - Average Earnings Index, March 11 - CPI (USD). \n**Sterling Verdict**: Potential gains today, targeting 214.98.";
const body = JSON.stringify({ chat_id: chatId, text: text, parse_mode: 'Markdown' });
const req = https.request({
  hostname: 'api.telegram.org',
  path: '/bot' + token + '/sendMessage',
  method: 'POST',
  headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(body) }
}, res => { let d = ''; res.on('data', c => d += c); res.on('end', () => console.log(d)); });
req.on('error', e => console.error(e.message));
req.write(body);
req.end();
